<script setup lang="ts">
import ConnectionPanel from '../components/ConnectionPanel.vue'
import { ref,onMounted,onUnmounted } from 'vue'
import { ElMessage,ElMessageBox } from 'element-plus'
import { request,post } from '../api/client'
interface Message{id:string;title:string;body:string;createdAt:string;telegramState:string;deliveryId?:string;deliveryError:string}
const messages=ref<Message[]>([]),error=ref(''),loading=ref(false);let timer:ReturnType<typeof setInterval>|undefined
const labels:Record<string,string>={sent:'Telegram已发送',pending:'等待投递',retry:'等待重试',sending:'发送中',outcome_unknown:'结果未知，需人工核对',failed:'投递失败',not_configured:'仅站内通知'}
async function refresh(){loading.value=true;try{messages.value=await request<Message[]>('/notifications');error.value=''}catch(e){error.value=e instanceof Error?e.message:'通知记录不可用'}finally{loading.value=false}}
async function retry(m:Message){try{await ElMessageBox.confirm(m.telegramState==='outcome_unknown'?'上一次可能已发送。请先在Telegram核对，再确认接受重复风险。':'将重新投递到相同版本的Telegram目标，不影响媒体任务。','重发通知',{confirmButtonText:'确认重发',cancelButtonText:'取消',type:'warning'});await post(`/notification-deliveries/${m.deliveryId}/retry`,{acceptDuplicateRisk:m.telegramState==='outcome_unknown'});ElMessage.success('通知重发已排队');await refresh()}catch(e){if(e instanceof Error)ElMessage.error(e.message)}}
onMounted(()=>{refresh();timer=setInterval(refresh,10000)});onUnmounted(()=>{if(timer)clearInterval(timer)})
</script>
<template><section class="page-heading"><div><h1>通知中心</h1><p>业务事件进入事务Outbox。发送失败不影响媒体入库。</p></div><div class="heading-actions"><el-button :loading="loading" @click="refresh">刷新</el-button><RouterLink to="/integrations" class="inline-link">配置Telegram</RouterLink></div></section><el-alert v-if="error" :title="error" type="error" :closable="false"/><section class="panel"><div v-for="message in messages" :key="message.id" class="notification-row"><div><h3>{{message.title}}</h3><p>{{message.body}}</p><small>{{new Date(message.createdAt).toLocaleString('zh-CN')}}</small></div><div><span class="status-badge" :class="message.telegramState==='sent'?'good':'neutral'">{{labels[message.telegramState]??message.telegramState}}</span><p class="field-hint">{{message.deliveryError}}</p><el-button v-if="message.deliveryId&&['failed','outcome_unknown'].includes(message.telegramState)" @click="retry(message)">人工重发</el-button></div></div><div v-if="messages.length===0" class="empty-state"><h3>还没有业务通知</h3><p>下载和媒体入库产生事件后，Worker会投递到这里和已启用的Telegram。</p></div></section><section class="note-panel"><strong>投递不确定性</strong><p>超时可能意味着消息已发送但回执丢失。此类记录不会自动重复发送，需先在Telegram中核对，避免重复通知。</p></section><ConnectionPanel :allowed-kinds="['telegram']" title="通知渠道"/></template>
